// condenses and clears PendingPushRemote.
func TestHandleTurnEnd_PushAfterCondensation(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

